const e=Object.freeze;export const DOOR_COUNT=4;export const START_DELAY_MS=3e3;export const SIGNAL_RUN_MS=52e3;export const MAX_RUN_MS=55e3;export const COOLDOWN_MS=400;export const START_WINDOW_MS=1200;export const END_WINDOW_MS=550;export const SLOT_COUNT=39;export function warningWindow(e){return Math.round(1200-e/38*650)}export function createSchedule(){const t=[];let n=3400,r=0;for(let s=0;s<39;s+=1){const o=warningWindow(s),c=(3*s+Math.floor(s/4))%4,i=[c];s>5&&s%9==6&&i.push((c+2+s%2)%4);for(const c of i)t.push(e({id:r++,slot:s,door:c,shadow:(c+1+s%2)%4,at:n,endsAt:n+o,window:o}));n+=o+375}return e(t)}export const CUE_PLAN=createSchedule();export function createRun(){return e({score:0,streak:0,parcels:3,hits:0,misses:0,falseAlarms:0,cooldownUntil:0,nextCue:0,active:e([]),finished:!1})}export function advanceRun(t,n){if(t.finished)return t;const r=[...t.active];let s=t.nextCue;for(;s<CUE_PLAN.length&&CUE_PLAN[s].at<=n;)r.push(CUE_PLAN[s++]);const o=r.filter(e=>e.endsAt<=n),c=Math.max(0,t.parcels-o.length);return e({...t,streak:o.length?0:t.streak,parcels:c,misses:t.misses+o.length,nextCue:s,active:e(r.filter(e=>e.endsAt>n)),finished:0===c||n>=55e3})}export function latchDoor(t,n,r){const s=advanceRun(t,r);if(s.finished)return e({run:s,event:"ended"});if(r<s.cooldownUntil)return e({run:s,event:"cooldown"});const o=s.active.find(e=>e.door===n);if(!o)return e({run:e({...s,falseAlarms:s.falseAlarms+1,cooldownUntil:r+400}),event:"false-alarm"});const c=Math.max(0,o.endsAt-r),i=Math.min(3,s.streak+1),a=(10+Math.floor(c/50))*i;return e({run:e({...s,score:s.score+a,streak:s.streak+1,hits:s.hits+1,active:e(s.active.filter(e=>e.id!==o.id))}),event:"latched",points:a,multiplier:i,remaining:c})}export function summarizeRun(t){const{score:n,hits:r,misses:s,falseAlarms:o,parcels:c}=t;return e({score:n,hits:r,misses:s,falseAlarms:o,parcels:c,secured:c>0})}